Lemma eager_used_ext : forall m1 m2,
  m_vmmaps m1 = m_vmmaps m2 -> m_vm_lazy m1 = m_vm_lazy m2 -> eager_used m1 = eager_used m2.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S80!1+6!1,7|600;!1+4!2+500!1'8#3!1'3#3!1'3#4!1'=4!1'8#4!1';!2'<56$m1;R+0$m2;R+0$H1;R!3+1+2!1'3#2!1'3#1$H2;R!3+112!1'8#2vd!6'9+23$v;R+2!3+1+:!1';!2'<!1'=#1!1'8#57!6'912$l;R1!3+1+:!1';!2'<5#17!2,>+:!1';!2'<!1'=326#14#2!3+1+:!1'?#4!1'?#3").
Qed.

