Definition art_ev_live (ev : aev) (l : list (Z * Z)) : list (Z * Z) :=
  match ev with
  | AMmapNull len r => (r, len) :: l
  | AMunmap addr len => List.filter (fun p => negb (fst p =? addr)) l
  | _ => l
  end.
