Definition SHHI : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!1,^K|\0007fff8000;").
Definition LSH_LO : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!1,^K|N3fff8000;").      Definition LSH_HI : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!1,^K|O0fff7000;").          (* [comment removed for export] *)
Definition HSH_LO : Z := 0x02008fff7000.  Definition HSH_HI : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!1,^K|\0007fff8000;").      (* [comment removed for export] *)
Definition in_shadow_rw (x : Z) : Prop := LSH_LO <= x < LSH_HI \/ HSH_LO <= x < HSH_HI.

