Lemma view_reveal : forall (H H' : word -> bool) M (lo hi : Z),
  (forall a : word, lo <= bv_unsigned a < hi -> H' a = false /\ M a <> None /\ (H a = true -> M a = Some (Z_to_bv 8 0))) ->
