Lemma restrict_mkst : forall (H : word -> bool) regs pc M rom,
  restrict H (mkst regs pc M rom) = mkst regs pc (mrestrict H M) rom.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S30!1+6!1,7|600;|30;%~R0!1+`R!1+6!1,71$H;R%~R0+^8$regs;R!2'dQ!1,7|21;0$pc;R0$M;R2$rom;R2!2,>+aK!5'dR/fx;#4#3!2'dM#5#2#1").
Qed.

