Theorem aruns_srealizes : forall (Q : list aev -> machine_state -> Prop) K model0,
  (forall log A ms model, BInv log A (ms_mem ms) model -> bmodel_rt model0 model ->
     Q log (restrict (bhid A model) ms) -> srealizes segs scfg (mkCfg ms model) K) ->
  forall log s, aruns segs EVOK GR Q log s ->
  forall A ms model, restrict (bhid A model) ms = s -> BInv log A (ms_mem ms) model -> bmodel_rt model0 model ->
  srealizes segs scfg (mkCfg ms model) K.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40!1+4+bG!1+4!2+5+:+:!4+c@#4#3!1'aN#2#1!1'aN#5$Q;R%~R0%~R+aKw$K;R'd;$model0;R+0$HQ;R%log;R0%A;R1%ms;R+aK%model;R+0%~R2%~R!2'c=#6#2%~R!2#9#6!2'd<!2'cA#5#3#4!4+d>/segs;/scfg;!2,d?#5#4#9$log;R0$s;R+aK$R;R!7+k0/segs;!4'g1/RES;/BUDGET;/LENMAX;/KMAX;!2'iV'h;/CEIL;/fx;#6#2#1$A;R1$ms;R+aK$model;R+0$Es;R!3+1+aK!2'd<!2'cA#3#1#2#5$B;R!4+c@#7#4!1'aN#3#2$Hrt;R!2'c=#:#3!B'k>#=#<#;#63#4#9$log';R0$A';R1$ms';R+aK$model';R+0$B';R2$Hrt';R!2'c=#@#2$~R!8'jY#<!1'aN#;#:#?#6#5!1'aN#4#3$Hq;R!2#D#7!2'd<!2'cA#6#4#5!7#B#8#7#6#5#4#3#1#9#8#7#6#5#4#3#2#1!4'k?#63#4#9").
